with filtered_employees as (select * from employees where job_title not in ('Analyst', 'Manager')), summary as (select case when year(hire_date) < 2024 then 'before_2024' when year(hire_date) = 2024 then '2024' else 'after_2024' end hire_cohort, count(case when job_title = 'Engineer' then 1 end) engineer_count from filtered_employees group by case when year(hire_date) < 2024 then 'before_2024' when year(hire_date) = 2024 then '2024' else 'after_2024' end) select hire_cohort, engineer_count from summary order by engineer_count asc;
